package com.perkvault.app;
import android.app.*;import android.content.*;import org.json.*;import java.time.*;
public class Reminder extends BroadcastReceiver {static void schedule(Context c){AlarmManager a=c.getSystemService(AlarmManager.class);PendingIntent p=PendingIntent.getBroadcast(c,3,new Intent(c,Reminder.class),PendingIntent.FLAG_IMMUTABLE);a.setInexactRepeating(AlarmManager.RTC_WAKEUP,System.currentTimeMillis()+3600000,AlarmManager.INTERVAL_DAY,p);}public void onReceive(Context c,Intent i){if(!c.getSharedPreferences("prefs",0).getBoolean("remind",true))return;JSONArray a=Store.read(c);int count=0;for(int j=0;j<a.length();j++){JSONObject o=a.optJSONObject(j);try{long days=java.time.temporal.ChronoUnit.DAYS.between(LocalDate.now(),LocalDate.parse(o.optString("expiry")));if(!o.optBoolean("used")&&(days==7||days==3||days==1||days==0)&&c.getSharedPreferences("prefs",0).getBoolean("day"+days,true))count++;}catch(Exception e){}}if(count==0)return;NotificationManager n=c.getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("expiry","Expiry reminders",NotificationManager.IMPORTANCE_DEFAULT));if(android.os.Build.VERSION.SDK_INT>=33&&c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)return;n.notify(4,new Notification.Builder(c,"expiry").setSmallIcon(android.R.drawable.ic_menu_recent_history).setContentTitle(count+" rewards expiring soon").setContentText("Check your wallet before they expire").setContentIntent(PendingIntent.getActivity(c,4,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).setAutoCancel(true).build());}}
